B.aBm=new A.he("Ask","spark","Ask Thara","\u0627\u0633\u0623\u0644 \u062b\u0631\u0627\u0621","Thara's assistant answers questions about your own money and can prepare changes for you. It works with Thara AI, online, and only after you allow it.","\u0645\u0633\u0627\u0639\u062f \u062b\u0631\u0627\u0621 \u064a\u062c\u064a\u0628 \u0639\u0646 \u0623\u0633\u0626\u0644\u062a\u0643 \u0639\u0646 \u0645\u0627\u0644\u0643 \u0648\u064a\u062c\u0647\u0651\u0632 \u0644\u0643 \u0627\u0644\u062a\u063a\u064a\u064a\u0631\u0627\u062a. \u064a\u0639\u0645\u0644 \u0628\u0640\xab\u0630\u0643\u0627\u0621 \u062b\u0631\u0627\u0621\xbb \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a\u060c \u0648\u0628\u0639\u062f \u0645\u0648\u0627\u0641\u0642\u062a\u0643 \u0641\u0642\u0637.",B.bfg)
B.azF=new A.bZ("Tap the round +, then Talk live (it is also in More). The first time, read what is sent and allow it.","\u0627\u0636\u063a\u0637 \u0639\u0644\u0649 \u0632\u0631 + \u0627\u0644\u062f\u0627\u0626\u0631\u064a \u062b\u0645 \u062a\u062d\u062f\u062b \u0645\u0628\u0627\u0634\u0631\u0629 (\u0648\u0647\u0648 \u0641\u064a \u0627\u0644\u0645\u0632\u064a\u062f \u0623\u064a\u0636\u064b\u0627). \u0641\u064a \u0623\u0648\u0644 \u0645\u0631\u0629 \u0627\u0642\u0631\u0623 \u0645\u0627 \u064a\u064f\u0631\u0633\u0644 \u0648\u0648\u0627\u0641\u0642 \u0639\u0644\u064a\u0647.")
B.aAs=new A.bZ("Speak naturally; Thara answers aloud. A record it prepares is shown for you to approve.","\u062a\u062d\u062f\u062b \u0628\u0637\u0628\u064a\u0639\u062a\u0643\u060c \u0648\u062b\u0631\u0627\u0621 \u064a\u062c\u064a\u0628 \u0628\u0635\u0648\u062a \u0645\u0633\u0645\u0648\u0639. \u0648\u0623\u064a \u062d\u0631\u0643\u0629 \u064a\u062c\u0647\u0651\u0632\u0647\u0627 \u062a\u064f\u0639\u0631\u0636 \u0639\u0644\u064a\u0643 \u0644\u062a\u0648\u0627\u0641\u0642 \u0639\u0644\u064a\u0647\u0627.")
B.aAD=new A.bZ("More, then Live talk settings, holds the switch, the microphone, where the voice plays, and a check of the connection.","\u0627\u0644\u0645\u0632\u064a\u062f \u062b\u0645 \u0625\u0639\u062f\u0627\u062f\u0627\u062a \u0627\u0644\u0645\u062d\u0627\u062f\u062b\u0629 \u0627\u0644\u0645\u0628\u0627\u0634\u0631\u0629 \u0641\u064a\u0647\u0627 \u0627\u0644\u0645\u0641\u062a\u0627\u062d \u0648\u0627\u0644\u0645\u064a\u0643\u0631\u0648\u0641\u0648\u0646 \u0648\u0645\u0643\u0627\u0646 \u0633\u0645\u0627\u0639 \u0627\u0644\u0635\u0648\u062a \u0648\u0641\u062d\u0635 \u0627\u0644\u0627\u062a\u0635\u0627\u0644.")
B.bun=s([B.azF,B.aAs,B.aAD],t.vS)
B.aB8=new A.he("Live","headset","Talk live","\u062a\u062d\u062f\u062b \u0645\u0628\u0627\u0634\u0631\u0629","Talk with Thara by voice, as on a call. Your voice goes online to Thara AI while you talk, so Thara asks before the first time.","\u062a\u062d\u062f\u062b \u0645\u0639 \u062b\u0631\u0627\u0621 \u0628\u0627\u0644\u0635\u0648\u062a \u0643\u0623\u0646\u0647\u0627 \u0645\u0643\u0627\u0644\u0645\u0629. \u0635\u0648\u062a\u0643 \u064a\u0630\u0647\u0628 \u0639\u0628\u0631 \u0627\u0644\u0625\u0646\u062a\u0631\u0646\u062a \u0625\u0644\u0649 \xab\u0630\u0643\u0627\u0621 \u062b\u0631\u0627\u0621\xbb \u0623\u062b\u0646\u0627\u0621 \u0627\u0644\u062d\u062f\u064a\u062b\u060c \u0644\u0630\u0644\u0643 \u064a\u0633\u062a\u0623\u0630\u0646\u0643 \u062b\u0631\u0627\u0621 \u0642\u0628\u0644 \u0623\u0648\u0644 \u0645\u0631\u0629.",B.bun)
B.aA0=new A.bZ("Open More, then Bank messages, and switch reading on. The phone asks you to allow reading messages.","\u0627\u0641\u062a\u062d \u0627\u0644\u0645\u0632\u064a\u062f \u062b\u0645 \u0631\u0633\u0627\u0626\u0644 \u0627\u0644\u0628\u0646\u0643 \u0648\u0634\u063a\u0651\u0644 \u0627\u0644\u0642\u0631\u0627\u0621\u0629. \u0633\u064a\u0637\u0644\u0628 \u0627\u0644\u0647\u0627\u062a\u0641 \u0625\u0630\u0646 \u0642\u0631\u0627\u0621\u0629 \u0627\u0644\u0631\u0633\u0627\u0626\u0644.")
